import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
const root='/home/deseti/projects/retempo';
const scratch='/home/deseti/.hermes/cache/scratch/retempo-dependency-triage';
const require=createRequire(root+'/package.json');
const {build:esbuild}=require('esbuild');
const names=Object.keys(JSON.parse(fs.readFileSync(root+'/docs/phase-5-evidence/dependency-audit.json','utf8')));
function packageOf(id){
 let d=path.dirname(id.replace(/\?.*$/,''));
 if(!path.isAbsolute(d)) d=path.resolve(root,d);
 while(d!==path.dirname(d)){
  const f=path.join(d,'package.json');
  if(fs.existsSync(f)) {try{const p=JSON.parse(fs.readFileSync(f,'utf8'));if(p.name)return {name:p.name,version:p.version,packagePath:path.relative(root,d)}}catch{}}
  d=path.dirname(d);
 }
 return null;
}
for(const [label,entry] of [['publicWorker','worker/src/index.ts'],['privateWorker','chain-worker/src/index.ts']]){
 const r=await esbuild({absWorkingDir:root,entryPoints:[entry],bundle:true,write:false,metafile:true,format:'esm',platform:'browser',target:'es2022',external:['cloudflare:*','node:*'],outdir:scratch+'/'+label,logLevel:'warning'});
 fs.writeFileSync(scratch+'/'+label+'-metafile.json',JSON.stringify(r.metafile,null,2));
 const hits=[];for(const [id,info] of Object.entries(r.metafile.inputs)){let pkg=packageOf(id);if(pkg&&names.includes(pkg.name)){let bytes=Object.values(r.metafile.outputs).reduce((n,o)=>n+(o.inputs[id]?.bytesInOutput||0),0);hits.push({id,...pkg,bytesInOutput:bytes,imports:info.imports});}}
 fs.writeFileSync(scratch+'/'+label+'-hits.json',JSON.stringify(hits,null,2)); console.log(label,JSON.stringify([...new Set(hits.map(x=>x.name+'@'+x.version))]));
}
const {build}=await import(require.resolve('vite'));
const react=(await import(require.resolve('@vitejs/plugin-react'))).default;
const {nodePolyfills}=await import(require.resolve('vite-plugin-node-polyfills'));
let graph, chunks;
await build({root,configFile:false,envDir:scratch+'/empty-env',cacheDir:scratch+'/vite-cache',plugins:[react(),nodePolyfills(),{name:'triage-record',generateBundle(_,bundle){graph=[...this.getModuleIds()].map(id=>({id,imports:this.getModuleInfo(id)?.importedIds||[],dynamicImports:this.getModuleInfo(id)?.dynamicallyImportedIds||[]}));chunks=Object.values(bundle).filter(x=>x.type==='chunk').map(x=>({fileName:x.fileName,isEntry:x.isEntry,isDynamicEntry:x.isDynamicEntry,imports:x.imports,dynamicImports:x.dynamicImports,modules:Object.entries(x.modules).map(([id,m])=>({id,...packageOf(id),renderedLength:m.renderedLength,renderedExports:m.renderedExports,removedExports:m.removedExports}))}));}}],resolve:{alias:{'@':root+'/src','@shared':root+'/shared'},dedupe:['react','react-dom']},build:{write:false,manifest:true,outDir:scratch+'/unused-dist',emptyOutDir:false}});
fs.writeFileSync(scratch+'/browser-graph.json',JSON.stringify(graph,null,2));fs.writeFileSync(scratch+'/browser-chunks.json',JSON.stringify(chunks,null,2));
console.log('browser',JSON.stringify([...new Set(chunks.flatMap(c=>c.modules.filter(m=>m.renderedLength>0).map(m=>m.name+'@'+m.version)))]));

